/* Compact QR Code generator — byte-mode, ECC L/M/Q/H, versions 1-40.
 *
 * A faithful, self-contained reimplementation of the QR Code spec
 * (ISO/IEC 18004) following the structure of nayuki/QR-Code-generator
 * (MIT). Written in-tree (ADR O1 deviation, operator-approved) so the
 * onboarding bundle has zero external fetch + no build step. Exposes
 * the same global surface onboard.js calls:
 *
 *   qrcodegen.QrCode.encodeText(text, qrcodegen.QrCode.Ecc.MEDIUM)
 *     → { size:int, getModule(x,y):bool }
 *
 * Byte mode only (the onboarding page encodes a URL — always bytes).
 * No kanji/numeric/alphanumeric segment optimisation; URLs don't
 * benefit and it keeps the file small + auditable.
 */
var qrcodegen = (function () {
  "use strict";

  // --- Galois field GF(256), primitive 0x11D ---------------------------
  var EXP = new Array(512), LOG = new Array(256);
  (function () {
    var x = 1;
    for (var i = 0; i < 255; i++) {
      EXP[i] = x; LOG[x] = i;
      x <<= 1;
      if (x & 0x100) x ^= 0x11D;
    }
    for (var j = 255; j < 512; j++) EXP[j] = EXP[j - 255];
  })();
  function gfMul(a, b) {
    if (a === 0 || b === 0) return 0;
    return EXP[LOG[a] + LOG[b]];
  }

  // --- Reed-Solomon ----------------------------------------------------
  function rsComputeDivisor(degree) {
    var result = new Uint8Array(degree);
    result[degree - 1] = 1;
    var root = 1;
    for (var i = 0; i < degree; i++) {
      for (var j = 0; j < degree; j++) {
        result[j] = gfMul(result[j], root);
        if (j + 1 < degree) result[j] ^= result[j + 1];
      }
      root = gfMul(root, 2);
    }
    return result;
  }
  function rsRemainder(data, divisor) {
    var result = new Uint8Array(divisor.length);
    for (var i = 0; i < data.length; i++) {
      var factor = data[i] ^ result[0];
      result.copyWithin(0, 1);
      result[result.length - 1] = 0;
      for (var j = 0; j < result.length; j++) result[j] ^= gfMul(divisor[j], factor);
    }
    return result;
  }

  // --- Per-version tables (ECC L,M,Q,H) --------------------------------
  // ECC codewords per block, indexed [ecc][version].
  var ECC_CW_PER_BLOCK = [
    [-1, 7, 10, 15, 20, 26, 18, 20, 24, 30, 18, 20, 24, 26, 30, 22, 24, 28, 30, 28, 28, 28, 28, 30, 30, 26, 28, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30],
    [-1, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26, 30, 22, 22, 24, 24, 28, 28, 26, 26, 26, 26, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28],
    [-1, 13, 22, 18, 26, 18, 24, 18, 22, 20, 24, 28, 26, 24, 20, 30, 24, 28, 28, 26, 30, 28, 30, 30, 30, 30, 28, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30],
    [-1, 17, 28, 22, 16, 22, 28, 26, 26, 24, 28, 24, 28, 22, 24, 24, 30, 28, 28, 26, 28, 30, 24, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30]
  ];
  // Number of error-correction blocks, indexed [ecc][version].
  var NUM_EC_BLOCKS = [
    [-1, 1, 1, 1, 1, 1, 2, 2, 2, 2, 4, 4, 4, 4, 4, 6, 6, 6, 6, 7, 8, 8, 9, 9, 10, 12, 12, 12, 13, 14, 15, 16, 17, 18, 19, 19, 20, 21, 22, 24, 25],
    [-1, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5, 5, 8, 9, 9, 10, 10, 11, 13, 14, 16, 17, 17, 18, 20, 21, 23, 25, 26, 28, 29, 31, 33, 35, 37, 38, 40, 43, 45, 47, 49],
    [-1, 1, 1, 2, 2, 4, 4, 6, 6, 8, 8, 8, 10, 12, 16, 12, 17, 16, 18, 21, 20, 23, 23, 25, 27, 29, 34, 34, 35, 38, 40, 43, 45, 48, 51, 53, 56, 59, 62, 65, 68],
    [-1, 1, 1, 2, 4, 4, 4, 5, 6, 8, 8, 11, 11, 16, 16, 18, 16, 19, 21, 25, 25, 25, 34, 30, 32, 35, 37, 40, 42, 45, 48, 51, 54, 57, 60, 63, 66, 70, 74, 77, 81]
  ];

  function eccIndex(ecc) { return ecc.ord; }

  function numRawDataModules(ver) {
    var result = (16 * ver + 128) * ver + 64;
    if (ver >= 2) {
      var numAlign = Math.floor(ver / 7) + 2;
      result -= (25 * numAlign - 10) * numAlign - 55;
      if (ver >= 7) result -= 36;
    }
    return result;
  }
  function numDataCodewords(ver, ecc) {
    var e = eccIndex(ecc);
    return Math.floor(numRawDataModules(ver) / 8)
      - ECC_CW_PER_BLOCK[e][ver] * NUM_EC_BLOCKS[e][ver];
  }

  // --- Ecc enum --------------------------------------------------------
  function Ecc(ord, formatBits) { this.ord = ord; this.formatBits = formatBits; }
  Ecc.LOW = new Ecc(0, 1);
  Ecc.MEDIUM = new Ecc(1, 0);
  Ecc.QUARTILE = new Ecc(2, 3);
  Ecc.HIGH = new Ecc(3, 2);

  // --- byte-mode segment encoding --------------------------------------
  function utf8Bytes(str) {
    var out = unescape(encodeURIComponent(str)); // → latin1 string of UTF-8 bytes
    var arr = new Uint8Array(out.length);
    for (var i = 0; i < out.length; i++) arr[i] = out.charCodeAt(i);
    return arr;
  }

  // --- QrCode ----------------------------------------------------------
  function QrCode(version, ecc, dataCodewords, mask) {
    this.version = version;
    this.size = version * 4 + 17;
    this.ecc = ecc;
    var sz = this.size;
    this.modules = [];
    this.isFunction = [];
    for (var i = 0; i < sz; i++) {
      this.modules.push(new Array(sz).fill(false));
      this.isFunction.push(new Array(sz).fill(false));
    }
    this.drawFunctionPatterns();
    var allCodewords = this.addEccAndInterleave(dataCodewords);
    this.drawCodewords(allCodewords);
    // Masking: if mask < 0 pick the best by penalty.
    if (mask < 0) {
      var minPenalty = Infinity;
      for (var m = 0; m < 8; m++) {
        this.applyMask(m);
        this.drawFormatBits(m);
        var penalty = this.getPenaltyScore();
        if (penalty < minPenalty) { mask = m; minPenalty = penalty; }
        this.applyMask(m); // undo
      }
    }
    this.mask = mask;
    this.applyMask(mask);
    this.drawFormatBits(mask);
    this.isFunction = null;
  }

  QrCode.prototype.getModule = function (x, y) {
    return 0 <= x && x < this.size && 0 <= y && y < this.size && this.modules[y][x];
  };

  QrCode.prototype.setFunctionModule = function (x, y, isDark) {
    this.modules[y][x] = isDark;
    this.isFunction[y][x] = true;
  };

  QrCode.prototype.drawFunctionPatterns = function () {
    var sz = this.size, i;
    // Timing patterns.
    for (i = 0; i < sz; i++) {
      this.setFunctionModule(6, i, i % 2 === 0);
      this.setFunctionModule(i, 6, i % 2 === 0);
    }
    // Finder patterns (3 corners).
    this.drawFinder(3, 3);
    this.drawFinder(sz - 4, 3);
    this.drawFinder(3, sz - 4);
    // Alignment patterns.
    var pos = this.alignmentPositions();
    var n = pos.length;
    for (i = 0; i < n; i++) {
      for (var j = 0; j < n; j++) {
        if (!((i === 0 && j === 0) || (i === 0 && j === n - 1) || (i === n - 1 && j === 0))) {
          this.drawAlignment(pos[i], pos[j]);
        }
      }
    }
    // Reserve format + version areas (filled later).
    this.drawFormatBits(0);
    this.drawVersion();
  };

  QrCode.prototype.drawFinder = function (cx, cy) {
    for (var dy = -4; dy <= 4; dy++) {
      for (var dx = -4; dx <= 4; dx++) {
        var dist = Math.max(Math.abs(dx), Math.abs(dy));
        var xx = cx + dx, yy = cy + dy;
        if (0 <= xx && xx < this.size && 0 <= yy && yy < this.size) {
          this.setFunctionModule(xx, yy, dist !== 2 && dist !== 4);
        }
      }
    }
  };

  QrCode.prototype.drawAlignment = function (cx, cy) {
    for (var dy = -2; dy <= 2; dy++) {
      for (var dx = -2; dx <= 2; dx++) {
        this.setFunctionModule(cx + dx, cy + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1);
      }
    }
  };

  QrCode.prototype.alignmentPositions = function () {
    var ver = this.version;
    if (ver === 1) return [];
    var numAlign = Math.floor(ver / 7) + 2;
    var step = (ver === 32) ? 26
      : Math.ceil((ver * 4 + 4) / (numAlign * 2 - 2)) * 2;
    var result = [6];
    for (var pos = this.size - 7; result.length < numAlign; pos -= step) {
      result.splice(1, 0, pos);
    }
    return result;
  };

  QrCode.prototype.drawFormatBits = function (mask) {
    var data = (this.ecc.formatBits << 3) | mask;
    var rem = data;
    for (var i = 0; i < 10; i++) rem = (rem << 1) ^ ((rem >>> 9) * 0x537);
    var bits = ((data << 10) | rem) ^ 0x5412;
    var j;
    // First copy.
    for (j = 0; j <= 5; j++) this.setFunctionModule(8, j, getBit(bits, j));
    this.setFunctionModule(8, 7, getBit(bits, 6));
    this.setFunctionModule(8, 8, getBit(bits, 7));
    this.setFunctionModule(7, 8, getBit(bits, 8));
    for (j = 9; j < 15; j++) this.setFunctionModule(14 - j, 8, getBit(bits, j));
    // Second copy.
    for (j = 0; j < 8; j++) this.setFunctionModule(this.size - 1 - j, 8, getBit(bits, j));
    for (j = 8; j < 15; j++) this.setFunctionModule(8, this.size - 15 + j, getBit(bits, j));
    this.setFunctionModule(8, this.size - 8, true); // always-dark module
  };

  QrCode.prototype.drawVersion = function () {
    if (this.version < 7) return;
    var rem = this.version;
    for (var i = 0; i < 12; i++) rem = (rem << 1) ^ ((rem >>> 11) * 0x1F25);
    var bits = (this.version << 12) | rem;
    for (var j = 0; j < 18; j++) {
      var bit = getBit(bits, j);
      var a = this.size - 11 + (j % 3), b = Math.floor(j / 3);
      this.setFunctionModule(a, b, bit);
      this.setFunctionModule(b, a, bit);
    }
  };

  QrCode.prototype.addEccAndInterleave = function (data) {
    var ver = this.version, ecc = this.ecc, e = eccIndex(ecc);
    var numBlocks = NUM_EC_BLOCKS[e][ver];
    var blockEccLen = ECC_CW_PER_BLOCK[e][ver];
    var rawCodewords = Math.floor(numRawDataModules(ver) / 8);
    var numShortBlocks = numBlocks - rawCodewords % numBlocks;
    var shortBlockLen = Math.floor(rawCodewords / numBlocks);
    var blocks = [];
    var rsDiv = rsComputeDivisor(blockEccLen);
    var k = 0;
    for (var i = 0; i < numBlocks; i++) {
      var datLen = shortBlockLen - blockEccLen + (i < numShortBlocks ? 0 : 1);
      var dat = Array.prototype.slice.call(data, k, k + datLen);
      k += datLen;
      var eccBytes = rsRemainder(dat, rsDiv);
      if (i < numShortBlocks) dat.push(0);
      for (var z = 0; z < eccBytes.length; z++) dat.push(eccBytes[z]);
      blocks.push(dat);
    }
    var result = [];
    for (var col = 0; col < blocks[0].length; col++) {
      for (var row = 0; row < blocks.length; row++) {
        if (col !== shortBlockLen - blockEccLen || row >= numShortBlocks) {
          result.push(blocks[row][col]);
        }
      }
    }
    return result;
  };

  QrCode.prototype.drawCodewords = function (data) {
    var sz = this.size, i = 0;
    for (var right = sz - 1; right >= 1; right -= 2) {
      if (right === 6) right = 5;
      for (var vert = 0; vert < sz; vert++) {
        for (var k = 0; k < 2; k++) {
          var x = right - k;
          var upward = ((right + 1) & 2) === 0;
          var y = upward ? sz - 1 - vert : vert;
          if (!this.isFunction[y][x] && i < data.length * 8) {
            this.modules[y][x] = getBit(data[i >>> 3], 7 - (i & 7));
            i++;
          }
        }
      }
    }
  };

  QrCode.prototype.applyMask = function (mask) {
    for (var y = 0; y < this.size; y++) {
      for (var x = 0; x < this.size; x++) {
        if (this.isFunction[y][x]) continue;
        var invert;
        switch (mask) {
          case 0: invert = (x + y) % 2 === 0; break;
          case 1: invert = y % 2 === 0; break;
          case 2: invert = x % 3 === 0; break;
          case 3: invert = (x + y) % 3 === 0; break;
          case 4: invert = (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0; break;
          case 5: invert = (x * y) % 2 + (x * y) % 3 === 0; break;
          case 6: invert = ((x * y) % 2 + (x * y) % 3) % 2 === 0; break;
          case 7: invert = ((x + y) % 2 + (x * y) % 3) % 2 === 0; break;
        }
        if (invert) this.modules[y][x] = !this.modules[y][x];
      }
    }
  };

  QrCode.prototype.getPenaltyScore = function () {
    var sz = this.size, score = 0, x, y, mods = this.modules;
    // Adjacent runs (rows + columns).
    for (y = 0; y < sz; y++) {
      var runColor = false, runX = 0;
      for (x = 0; x < sz; x++) {
        if (mods[y][x] === runColor) { runX++; if (runX === 5) score += 3; else if (runX > 5) score++; }
        else { runColor = mods[y][x]; runX = 1; }
      }
    }
    for (x = 0; x < sz; x++) {
      var rc = false, runY = 0;
      for (y = 0; y < sz; y++) {
        if (mods[y][x] === rc) { runY++; if (runY === 5) score += 3; else if (runY > 5) score++; }
        else { rc = mods[y][x]; runY = 1; }
      }
    }
    // 2x2 blocks.
    for (y = 0; y < sz - 1; y++) {
      for (x = 0; x < sz - 1; x++) {
        var c = mods[y][x];
        if (c === mods[y][x + 1] && c === mods[y + 1][x] && c === mods[y + 1][x + 1]) score += 3;
      }
    }
    // Balance of dark modules.
    var dark = 0;
    for (y = 0; y < sz; y++) for (x = 0; x < sz; x++) if (mods[y][x]) dark++;
    var total = sz * sz;
    var k = Math.ceil(Math.abs(dark * 20 - total * 10) / total) - 1;
    score += k * 10;
    return score;
  };

  function getBit(x, i) { return ((x >>> i) & 1) !== 0; }

  // --- public: encode a string (byte mode) -----------------------------
  QrCode.encodeText = function (text, ecc) {
    var bytes = utf8Bytes(text);
    // Find the smallest version (1-40) that fits at this ECC level.
    var ver, dataCapacityBits, usedBits;
    for (ver = 1; ver <= 40; ver++) {
      dataCapacityBits = numDataCodewords(ver, ecc) * 8;
      var ccBits = (ver <= 9) ? 8 : 16; // byte-mode char-count bits
      usedBits = 4 + ccBits + bytes.length * 8;
      if (usedBits <= dataCapacityBits) break;
    }
    if (ver > 40) throw new Error("Data too long for QR (max version exceeded)");

    // Build the bit buffer: mode (0100) + char count + data.
    var bb = [];
    function appendBits(val, len) {
      for (var i = len - 1; i >= 0; i--) bb.push((val >>> i) & 1);
    }
    appendBits(4, 4); // byte mode
    appendBits(bytes.length, ver <= 9 ? 8 : 16);
    for (var i = 0; i < bytes.length; i++) appendBits(bytes[i], 8);

    // Terminator + bit/byte padding.
    var capacity = numDataCodewords(ver, ecc) * 8;
    appendBits(0, Math.min(4, capacity - bb.length));
    while (bb.length % 8 !== 0) bb.push(0);
    for (var pad = 0xEC; bb.length < capacity; pad ^= 0xEC ^ 0x11) appendBits(pad, 8);

    // Pack bits into bytes.
    var dataCodewords = new Uint8Array(bb.length / 8);
    for (var j = 0; j < bb.length; j++) dataCodewords[j >>> 3] |= bb[j] << (7 - (j & 7));

    return new QrCode(ver, ecc, dataCodewords, -1);
  };

  QrCode.Ecc = Ecc;
  return { QrCode: QrCode };
})();

// Expose for both browser global + any CommonJS-style probing.
if (typeof window !== "undefined") window.qrcodegen = qrcodegen;
if (typeof module !== "undefined" && module.exports) module.exports = qrcodegen;
